(() => {
  const width = 620, height = 620, cx = width / 2, cy = height / 2;
  const points = [];
  const maxTheta = spiralTurns * 2 * Math.PI;
  const maxR = 275;
  for (let i = 0; i <= 1400; i++) {
    const t = maxTheta * i / 1400;
    const r = maxR * t / maxTheta;
    points.push([cx + r * Math.cos(t), cy + r * Math.sin(t)]);
  }
  const d = points.map((p, i) => `${i ? 'L' : 'M'}${p[0].toFixed(2)},${p[1].toFixed(2)}`).join(' ');
  return htl.html`<div style="max-width:650px;font-family:system-ui,sans-serif">
    <svg viewBox="0 0 ${width} ${height}" width="100%" role="img" aria-label="Archimedean spiral" style="display:block;background:#fff;border:1px solid #ddd;border-radius:12px">
      <path d="${d}" fill="none" stroke="#2563eb" stroke-width="3" stroke-linecap="round"/>
      <circle cx="${cx}" cy="${cy}" r="4" fill="#dc2626"/>
    </svg>
  </div>`;
})()

