(() => {
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const r = 120, color = d3.scaleOrdinal(data.map(d => d.task), d3.schemeTableau10);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.6).outerRadius(r * 0.6);
  const arcs = d3.pie().sort(null).value(d => d.value)(data);
  const svg = d3.create("svg").attr("viewBox", [-r - 10, -r - 10, 2 * r + 20, 2 * r + 20]).attr("width", 320).style("font", "12px sans-serif");
  svg.selectAll("path").data(arcs).join("path").attr("d", arc).attr("fill", d => color(d.data.task)).attr("stroke", "white");
  svg.selectAll("text").data(arcs).join("text").attr("transform", d => `translate(${label.centroid(d)})`).attr("text-anchor", "middle").attr("fill", "white")
    .text(d => `${d.data.task} ${d.data.value}%`);
  return svg.node();
})()
